import { formatNumber, formatTruncatedNumber } from "./../utils";
import { describe, it, expect } from "vitest";
describe("formatNumber", () => {
    let result;
    describe("formatNumber formats numbers correctly", () => {
        it("Given format number is called", () => {
            result = formatNumber(123123123);
        });
        it("Expect it to format data correctly", () => {
            expect(result).to.equal("123,123,123");
        });
    });
    describe("formatNumber formats number with fractional part", () => {
        it("Given formatNumber is called on number with fractional part", () => {
            result = formatNumber(12.34);
        });
        it("Expect it to format data with one fractional digit", () => {
            expect(result).to.equal("12.3");
        });
    });
    describe("formatNumber takes number of fractional digits as an option", () => {
        it("Given formatNumber is called with option of 3 fractional parts", () => {
            result = formatNumber(12.34567, { digits: 3 });
        });
        it("Expect it to format data with three fractional digits", () => {
            expect(result).to.equal("12.346");
        });
    });
    describe("formatNumber default value", () => {
        it("Given formatNumber is called no arguments", () => {
            result = formatNumber();
        });
        it("Expect it to use the default", () => {
            expect(result).to.equal("0");
        });
    });
    describe("formatNumber default value when value is null", () => {
        it("Given formatNumber is called with null value", () => {
            result = formatNumber(null);
        });
        it("Expect it to use the default", () => {
            expect(result).to.equal("0");
        });
    });
});
describe("formatTruncatedNumber", () => {
    let actualNumber;
    describe("formatTruncatedNumber for number less than a thousand", () => {
        it("Given format number shorthand is called", () => {
            actualNumber = formatTruncatedNumber(325);
        });
        it("Expect it to format the number correctly", () => {
            expect(actualNumber).to.be.equal("325");
        });
    });
    describe("formatTruncatedNumber for number less than a thousand with default digits specified", () => {
        it("Given format number shorthand is called", () => {
            actualNumber = formatTruncatedNumber(321.0413, { digits: 3 });
        });
        it("Expect it to format the number correctly with the default digits", () => {
            expect(actualNumber).to.be.equal("321.041");
        });
    });
    describe("formatTruncatedNumber for number in the thousands with default digits specified", () => {
        it("Given format number shorthand is called", () => {
            actualNumber = formatTruncatedNumber(32123.0413, { digits: 2 });
        });
        it("Expect it to format the number correctly with the default digits ignored", () => {
            expect(actualNumber).to.be.equal("32.1k");
        });
    });
    describe("formatTruncatedNumber for a number in the thousands", () => {
        it("Given format number shorthand is called", () => {
            actualNumber = formatTruncatedNumber(34531);
        });
        it("Expect it to format the number correctly", () => {
            expect(actualNumber).to.be.equal("34.5k");
        });
    });
    describe("formatTruncatedNumber for a number in the millions", () => {
        it("Given format number shorthand is called", () => {
            actualNumber = formatTruncatedNumber(4323451);
        });
        it("Expect it to format the number correctly", () => {
            expect(actualNumber).to.be.equal("4.3m");
        });
    });
    describe("formatTruncatedNumber for a number in the billions", () => {
        it("Given format number shorthand is called", () => {
            actualNumber = formatTruncatedNumber(132924323451);
        });
        it("Expect it to format the number correctly", () => {
            expect(actualNumber).to.be.equal("132.9b");
        });
    });
    describe("formatTruncatedNumber for a number in the trillions", () => {
        it("Given format number shorthand is called", () => {
            actualNumber = formatTruncatedNumber(42132924323451);
        });
        it("Expect it to format the number correctly", () => {
            expect(actualNumber).to.be.equal("42.1t");
        });
    });
    describe("formatTruncatedNumber for a number in the quadrillions", () => {
        it("Given format number shorthand is called", () => {
            actualNumber = formatTruncatedNumber(3203342132924323);
        });
        it("Expect it to format the number correctly", () => {
            expect(actualNumber).to.be.equal("3.2q");
        });
    });
});
